const baseResults = $('Calculate Client Health').all().map(item => item.json);
const clients = $('Search Active Paying Clients').all().map(item => item.json);
const meetings = $input.all().map(item => item.json);
const clientsById = new Map(clients.map(client => [client.id, client]));
const value = (row, name) => row[name] ?? row.fields?.[name];
const numeric = v => { const raw = Array.isArray(v) ? v[0] : (v?.value ?? v); const n = Number(raw); return Number.isFinite(n) ? n : 0; };
const linkedIds = v => (Array.isArray(v) ? v : []).map(x => typeof x === 'string' ? x : x?.id).filter(Boolean);

const meetingsByClient = new Map();
for (const meeting of meetings) {
  for (const clientId of linkedIds(value(meeting, 'Clients Table'))) {
    meetingsByClient.set(clientId, (meetingsByClient.get(clientId) ?? 0) + 1);
  }
}

const now = new Date();
const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
const elapsedDays = now.getDate();
const elapsedRatio = elapsedDays / daysInMonth;

return baseResults.map(base => {
  const result = { ...base };
  const client = clientsById.get(result.recordId) ?? {};
  const meetingsBooked = meetingsByClient.get(result.recordId) ?? 0;
  const clientKpi = numeric(value(client, 'Calls Booked KPI (Client)'));
  const internalKpi = numeric(value(client, 'Calls Booked KPI (Internal)'));
  const onboardingKpi = numeric(value(client, 'Calls Booked KPI (from Onboarding)'));
  const explicitKpi = clientKpi || internalKpi || onboardingKpi;
  const accountCount = Number(result.totalAccounts ?? 0);
  const capacityMidpoint = Math.max(1, accountCount * 0.15);
  const capacityLow = Math.max(1, accountCount * 0.10);
  const capacityHigh = Math.max(1, accountCount * 0.20);
  const monthlyGoal = explicitKpi > 0
    ? (accountCount > 0 ? Math.min(Math.max(explicitKpi, capacityLow), capacityHigh) : explicitKpi)
    : capacityMidpoint;
  const expectedByToday = monthlyGoal * elapsedRatio;
  const paceRatio = expectedByToday > 0 ? meetingsBooked / expectedByToday : 1;

  if (result.health !== 'Onboarding') {
    const paceReason = `${meetingsBooked} meetings booked MTD; ${expectedByToday.toFixed(1)} expected by today toward a ${monthlyGoal.toFixed(1)} monthly goal (${Math.round(paceRatio * 100)}% of pace)`;
    if (elapsedDays > 5 && paceRatio < 0.50) {
      result.health = 'At Risk';
      result.reasons = `${result.reasons}; ${paceReason}`;
    } else if (paceRatio < 0.80) {
      if (result.health === 'Healthy') result.health = 'Needs Attention';
      result.reasons = `${result.reasons}; ${paceReason}`;
    }
  }

  result.meetingsBookedThisMonth = meetingsBooked;
  result.monthlyMeetingGoal = Math.round(monthlyGoal * 10) / 10;
  result.expectedMeetingsByToday = Math.round(expectedByToday * 10) / 10;
  result.meetingPacePercent = Math.round(paceRatio * 1000) / 10;
  return { json: result };
});

const clients = $('Search Active Paying Clients').all().map(item => item.json);
const clientsById = new Map(clients.map(client => [client.id, client]));
const value = (row, name) => row[name] ?? row.fields?.[name];
const numeric = v => {
  const raw = Array.isArray(v) ? v[0] : (v?.value ?? v);
  const n = Number(raw);
  return Number.isFinite(n) ? n : 0;
};

return $input.all().map(item => {
  const result = { ...item.json };
  const client = clientsById.get(result.recordId) ?? {};
  const callsBooked = numeric(value(client, 'Calls Booked - Last 30 days'));
  const clientKpi = numeric(value(client, 'Calls Booked KPI (Client)'));
  const internalKpi = numeric(value(client, 'Calls Booked KPI (Internal)'));
  const onboardingKpi = numeric(value(client, 'Calls Booked KPI (from Onboarding)'));
  const bookingKpi = clientKpi || internalKpi || onboardingKpi;

  if (result.health !== 'Onboarding' && bookingKpi > 0) {
    const ratio = callsBooked / bookingKpi;
    const performanceReason = `${callsBooked} of ${bookingKpi} booked-meeting KPI achieved in the last 30 days (${Math.round(ratio * 100)}%)`;
    if (ratio < 0.50) {
      result.health = 'At Risk';
      result.reasons = `${result.reasons}; ${performanceReason}`;
    } else if (ratio < 0.80) {
      if (result.health === 'Healthy') result.health = 'Needs Attention';
      result.reasons = `${result.reasons}; ${performanceReason}`;
    }
    result.callsBooked = callsBooked;
    result.bookingKpi = bookingKpi;
    result.bookingPerformance = Math.round(ratio * 1000) / 10;
  }
  return { json: result };
});

const clients = $('Search Active Paying Clients').all().map(item => item.json);
const accounts = $input.all().map(item => item.json);
const checkedAt = new Date().toISOString();

const value = (row, name) => row[name] ?? row.fields?.[name];
const selectName = v => typeof v === 'string' ? v : (v?.name ?? '');
const linkedIds = v => (Array.isArray(v) ? v : []).map(x => typeof x === 'string' ? x : x?.id).filter(Boolean);
const reasonNames = v => (Array.isArray(v) ? v : []).map(x => typeof x === 'string' ? x : x?.name).filter(Boolean);
const severeReasons = new Set(['Poor Inbox Placement', 'Blacklist', 'Manual Review']);

const accountsByClient = new Map();
for (const account of accounts) {
  for (const clientId of linkedIds(value(account, 'Client'))) {
    if (!accountsByClient.has(clientId)) accountsByClient.set(clientId, []);
    accountsByClient.get(clientId).push(account);
  }
}

const updates = [];
for (const client of clients) {
  const recordId = client.id;
  const name = value(client, 'Name') ?? recordId;
  const onboardingComplete = Boolean(value(client, 'Onboarding_form_submitted'));
  const startDate = value(client, 'Client Start Date');
  const monthlyFee = Number(value(client, 'Monthly Fee') ?? 0);
  const outstanding = Number(value(client, 'Outstanding Receivables') ?? 0);
  const revenueMatch = String(value(client, 'Revenue Match Status') ?? '');
  const clientAccounts = accountsByClient.get(recordId) ?? [];

  let atRiskAccounts = 0;
  let severeAccounts = 0;
  const accountReasons = new Set();
  for (const account of clientAccounts) {
    const status = selectName(value(account, 'Status'));
    const reasons = reasonNames(value(account, 'Health Reason'));
    if (status === 'At Risk') atRiskAccounts += 1;
    if (reasons.some(r => severeReasons.has(r))) severeAccounts += 1;
    for (const r of reasons) accountReasons.add(r);
  }

  const totalAccounts = clientAccounts.length;
  const atRiskRatio = totalAccounts ? atRiskAccounts / totalAccounts : 0;
  const severeRatio = totalAccounts ? severeAccounts / totalAccounts : 0;
  const financialSevere = outstanding > 0 && outstanding >= Math.max(monthlyFee, 1);
  const emailSevere = totalAccounts >= 5 && (atRiskRatio >= 0.20 || severeRatio >= 0.10);

  let health = 'Healthy';
  const reasons = [];
  if (!onboardingComplete || !startDate) {
    health = 'Onboarding';
    if (!onboardingComplete) reasons.push('Onboarding form is incomplete');
    if (!startDate) reasons.push('Client start date is missing');
  } else if (financialSevere || emailSevere) {
    health = 'At Risk';
    if (financialSevere) reasons.push(`Outstanding receivables ($${outstanding.toFixed(2)}) are at least one monthly fee`);
    if (emailSevere) reasons.push(`${atRiskAccounts} of ${totalAccounts} email accounts are at risk`);
  } else {
    if (outstanding > 0) reasons.push(`Outstanding receivables: $${outstanding.toFixed(2)}`);
    if (revenueMatch && revenueMatch !== 'Matched') reasons.push(`Revenue match status: ${revenueMatch}`);
    if (atRiskAccounts > 0) reasons.push(`${atRiskAccounts} of ${totalAccounts} email accounts need attention`);
    if (totalAccounts === 0) reasons.push('No linked email accounts found');
    if (reasons.length) health = 'Needs Attention';
  }

  if (!reasons.length) reasons.push('Onboarding complete, payments clear, and email accounts healthy');
  if (accountReasons.size) reasons.push(`Email signals: ${[...accountReasons].join(', ')}`);

  updates.push({ json: { recordId, name, health, reasons: reasons.join('; '), checkedAt, totalAccounts, atRiskAccounts } });
}

return updates;

const calculated = $('Apply Monthly Meeting Pace').all().map(item => item.json);
const counts = calculated.reduce((acc, row) => { acc[row.health] = (acc[row.health] ?? 0) + 1; return acc; }, {});
return [{ json: { status: 'completed', clientsChecked: calculated.length, counts, checkedAt: new Date().toISOString() } }];
